class Splash : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        window.setFlags(
            android.view.WindowManager.LayoutParams.FLAG_FULLSCREEN,
            android.view.WindowManager.LayoutParams.FLAG_FULLSCREEN
        )
        setContentView(R.layout.activity_splash)
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }
        val videoView = findViewById<VideoView>(R.id.videoView)
        //AtomOpsApp.savePreferences(Constants.REFRESH,"eyJhbGciOiJSUzI1NiJ9..aAKTgsbOQ669TzBLJhDY785n8LA-4jkiAxyXiJWZmg8qyDDISk8giTsOaHjyIeu5in-3-euVjxdPV1UBTmyvUAO01LZnp71njPlFaO0Pnn0frGoxbMEB2y3n4BtYO9fy0qrBoHcXWFPj5M34Tit3UM5WHdKwhful6ipEpLU-KcIEP5N74acfEkq8V3Z23SaWLLvBzNe4QPMFjWHMD47nA50fdzkTh_u-FRtMSA3GQu7sp7luznIx1nEBXmD-ojqqrDaEEfIRuqFZbUh6j3yfamkCY03rgPazb0f4-wyjHADLKTb3njRvdUNoMUfx04Ge5MXwVyq709yl7SIyH75nFQ")
        // Points to res/raw/splash_video.mp4
        val uri = Uri.parse("android.resource://$packageName/" + R.raw.splashvideo)
        videoView.setVideoURI(uri)

        videoView.setOnPreparedListener { mp ->
            mp.isLooping = false      // set true if you want it to loop instead of navigating away
            videoView.start()
        }

        videoView.setOnCompletionListener {
            goToMainActivity()
        }

        // Optional: skip on tap
        videoView.setOnClickListener {

            goToMainActivity()
        }

    }

    private fun goToMainActivity() {
        if(AtomOpsApp.getPreferences(Constants.ISLOGIN,"false").equals("true")){
            reReshToken()

        }

        else{
            startActivity(Intent(this, LoginAct::class.java))
        }
       // finish()

    }
    private fun reReshToken() {
        lifecycleScope.launch {
            try {
                val response = ApiClient.getRetrofitclient()
                    .create(ServiceInterface::class.java)
                    .refreshToken(TokenMod(AtomOpsApp.getPreferences(Constants.REFRESH, "")))

                if (response.isSuccessful) {
                    startActivity(Intent(this@Splash, Dashboard::class.java))
                    finish()
                } else if (response.code() == 401 || response.code() == 403) {
                    // Refresh token is invalid, so retrying won't help. Go to login.
                    startActivity(Intent(this@Splash, LoginAct::class.java))
                    finish()
                } else {
                    showRetryDialog("Error(${response.code()})", Utils.getHttpErrorMessage(response.code(),""))
                }
            } catch (e: Exception) {
                showRetryDialog("Error", Utils.getErrorMessage(e))
            }
        }
    }

    private fun showRetryDialog(title: String, message: String) {
        if (isFinishing || isDestroyed) return
        Utils.showDialog(
            this, title, message,
            "Retry", "Login Again", R.drawable.ic_baseline_error_24,
            { reReshToken() },   // user chooses to retry, so no automatic loop
            { startActivity(Intent(this@Splash, LoginAct::class.java)) }
        )
    }
}